#include <iostream>
#include <string>
#include <vector>

std::string quote(const std::string& arg)
{
    return arg;
}

int main()
{
    std::vector<std::string> args{"tool.exe", "a b", "plain", "say \"hi\"", "C:\\my dir\\"};
    for (const auto& a : args) std::cout << quote(a) << ' ';
}
